{
  "diesel": {
    "current_stock": 5000,
    "unit": "liters"
  },
  "gasoline": {
    "current_stock": 3000,
    "unit": "liters"
  },
  "kerosene": {
    "current_stock": 1500,
    "unit": "liters"
